FROM penguins |> WHERE body_mass_g IS NOT NULL |> EXTEND bin(body_mass_g, maxbins => 40) OVER () AS body_mass_g_bin |> AGGREGATE count(*) AS n GROUP BY body_mass_g_bin, species |> CALL impute(body_mass_g_bin, [species], n, value => 0, fill_gaps => true, flag => imputed) |> EXTEND stack(n) OVER (PARTITION BY body_mass_g_bin ORDER BY species DESC NULLS FIRST, n ASC NULLS LAST, imputed ASC NULLS LAST) AS n_stack |> AGGREGATE area(x => scaled(body_mass_g_bin, title => 'body_mass_g'), y => scaled(n_stack, title => 'count(*)'), color => species, orient => 'vertical') AS area
